<template>
<v-container>
        <v-row>
          <v-col
            v-for="card in !loading ? Cards : 12"
            :key="card.categoryName"
            xs="6"
            md="3"
          >
            <div v-if="!loading" >
                <Card  :card="card"/>
            </div>
            <div v-else>
                <v-skeleton-loader
                class="mx-auto"
                max-width="300"
                type="card" >
                </v-skeleton-loader>
            </div>
          </v-col>
        </v-row>
      </v-container>
</template>

<script>
import Card from './Card.vue';
import { db } from '../firebase';

export default {
  name: 'Cards',
  components: {
    Card,
  },
  props: {
    limit: Boolean,
  },
  data() {
    return {
      loading: true,
      Cards: [],
      db,
    };
  },
  created() {
    if (this.limit) {
      db.collection('categories').limit(4).get().then((querySnapshot) => {
        const documents = querySnapshot.docs.map((doc) => doc.data());
        this.Cards = documents;
        this.loading = false;
      });
    } else {
      db.collection('categories').get().then((querySnapshot) => {
        const documents = querySnapshot.docs.map((doc) => doc.data());
        this.Cards = documents;
        this.loading = false;
      });
    }
  },

};
</script>

