// Archive build: the Firebase project behind StickerHub is gone, so this file
// stands in for Firestore with an in-memory copy of the sticker metadata.
// It implements only the calls the app makes: collection().where().limit().get(),
// collection().doc().get()/update()/set(). Writes last until the page reloads.
// The original sticker images are lost, so each sticker is drawn as an SVG from its name.
import stickerData from './mock/stickers.json';

const PALETTE = ['#1abc9c', '#f39c12', '#9b59b6', '#e74c3c', '#3498db', '#16a085', '#d35400', '#2c3e50'];

function colorFor(text) {
  let hash = 0;
  for (let i = 0; i < text.length; i += 1) hash = (hash * 31 + text.charCodeAt(i)) % 9973;
  return PALETTE[hash % PALETTE.length];
}

function escapeXml(text) {
  return text.replace(/[<>&'"]/g, (c) => ({
    '<': '&lt;', '>': '&gt;', '&': '&amp;', "'": '&apos;', '"': '&quot;',
  }[c]));
}

function wrap(text, width) {
  const lines = [];
  text.split(/\s+/).forEach((word) => {
    const last = lines[lines.length - 1];
    if (last && `${last} ${word}`.length <= width) lines[lines.length - 1] = `${last} ${word}`;
    else lines.push(word);
  });
  return lines.slice(0, 3);
}

function svgUrl(body, background) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 300"><rect width="400" height="300" fill="${background}"/>${body}</svg>`;
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}

function textLines(lines, size, fill) {
  const start = 150 - ((lines.length - 1) * size * 0.6);
  return lines.map((line, i) => `<text x="200" y="${start + i * size * 1.2}" font-family="Montserrat, Arial, sans-serif" font-weight="700" font-size="${size}" fill="${fill}" text-anchor="middle" dominant-baseline="middle">${escapeXml(line)}</text>`).join('');
}

function stickerImage(name, category) {
  const color = colorFor(category);
  const lines = wrap(name || '?', 12);
  const size = lines.length > 1 ? 30 : 38;
  const blob = `<g transform="rotate(-4 200 150)"><rect x="90" y="45" width="220" height="210" rx="42" fill="#fff" stroke="#fff" stroke-width="16"/><rect x="98" y="53" width="204" height="194" rx="36" fill="${color}"/></g>`;
  return svgUrl(blob + textLines(lines, size, '#fff'), '#f4f1ea');
}

function categoryImage(name) {
  const color = colorFor(name);
  // Category name is already the card title, so the cover is just a few blank stickers.
  const shapes = [[70, 60, -12, 90], [250, 40, 9, 110], [150, 150, -4, 120], [300, 180, 14, 80]]
    .map(([x, y, angle, size]) => `<rect x="${x}" y="${y}" width="${size}" height="${size}" rx="${size / 5}"
      fill="#fff" opacity=".22" transform="rotate(${angle} ${x + size / 2} ${y + size / 2})"/>`)
    .join('');
  return svgUrl(shapes, color);
}

const stickers = new Map(stickerData.map((s) => [s.id, {
  ...s,
  stickerImageURL: stickerImage(s.stickerName, s.category),
}]));

const categories = new Map();
stickerData.forEach((s) => {
  if (!categories.has(s.category)) {
    categories.set(s.category, {
      categoryName: s.category,
      categoryImageURL: categoryImage(s.category),
    });
  }
});

const store = { stickers, categories };

function snapshot(id, data) {
  return { id, exists: data !== undefined, data: () => (data ? { ...data } : undefined) };
}

function query(name, filters = [], max = Infinity) {
  const matches = (doc) => filters.every(([field, op, value]) => {
    if (op === '==') return doc[field] === value;
    if (op === 'array-contains') return (doc[field] || []).includes(value);
    return false;
  });
  return {
    where: (field, op, value) => query(name, [...filters, [field, op, value]], max),
    limit: (n) => query(name, filters, n),
    get: async () => {
      const docs = [...store[name]]
        .filter(([, d]) => matches(d))
        .slice(0, max)
        .map(([id, d]) => snapshot(id, d));
      return {
        docs, size: docs.length, empty: docs.length === 0, forEach: (fn) => docs.forEach(fn),
      };
    },
  };
}

export const db = {
  collection: (name) => ({
    ...query(name),
    doc: (id) => ({
      get: async () => snapshot(id, store[name].get(id)),
      set: async (data) => {
        const doc = { ...data };
        if (name === 'categories' && !doc.categoryImageURL) doc.categoryImageURL = categoryImage(id);
        store[name].set(id, doc);
      },
      update: async (data) => {
        if (!store[name].has(id)) throw new Error('No such document');
        store[name].set(id, { ...store[name].get(id), ...data });
      },
    }),
  }),
};

export const storage = null;
